-- Generated by scripts/generate-sfm-gloss-migrations.js - do not edit.
-- Imports Indonesian interlinear glosses for the book of Malachi
-- (Mal) from src/data/sfm/39MALIGIHG.SFM, aligned to the `word`
-- rows of the platform database per src/data/sfm/gloss-alignment-report.txt:
--   * USFM-MORE: gloss-only tokens with no Hebrew word are dropped
--     (1 token(s))
--   * DB-MORE: un-glossed word rows are left without a gloss
--     (0 word(s))
--   * MULTI-WORD: the word rows covered by one gloss token become one
--     multi-word phrase (0 phrase(s) over 0 word(s))
--   * SPLIT-WORD: the tokens that gloss one word row are combined into
--     a single gloss (1 word(s))
-- DB verses of the book with no USFM gloss data are likewise left
-- un-glossed (see the report's data-completeness section).
--
-- Glosses are attributed to no user (phrase.created_by and
-- gloss.updated_by are NULL) with source IMPORT and state APPROVED.
--
-- Depends on:
-- 26-09-16-single-word-suggestion-counts.schema.sql (the fixed gloss
-- suggestion triggers this import relies on), which is why this
-- migration is dated after it.
--
-- 55 verses imported: 876 single-word
-- glosses, 0 multi-word phrases covering 0
-- words, 1 split-word glosses (876 words
-- glossed in total).

begin;

do $$
begin
  if not exists (select 1 from language where code = 'ind') then
    values (generate_ulid(), 'ind', 'Indonesian', 'Bahasa Indonesia', '{}');
  end if;
end $$;

-- The phrase id sequence lags behind the max phrase id (phrases were
-- bulk-inserted with explicit ids), so resync it before creating phrases.
select setval('phrase_id_seq', greatest((select coalesce(max(id), 0) from phrase), (select last_value from phrase_id_seq)) + 1, false);

-- One row per gloss entry: `n` numbers the entries and `word_ids` holds
-- the word row(s) the gloss covers (a single id for a single-word gloss,
-- several ids in word order for a multi-word gloss / ketiv-qere pair).
create temp table _sfm_gloss (
  n int primary key,
  word_ids text[] not null,
  gloss text not null
) on commit drop;


create temp table _sfm_unit_word on commit drop as
select g.n, w.word_id
from _sfm_gloss g
cross join unnest(g.word_ids) as w(word_id);

do $$
begin
  -- every word id must be a word row of this book
  if exists (
    select 1 from _sfm_unit_word as uw
    where not exists (
      select 1 from word as w
      join verse as v on v.id = w.verse_id
      where w.id = uw.word_id and v.book_id = 39
    )
  ) then
    raise exception 'Unknown or non-Mal word id in import data';
  end if;

  -- a word row must not be imported by two gloss entries
  if exists (
    select 1 from _sfm_unit_word group by word_id having count(*) > 1
  ) then
    raise exception 'Word id imported by more than one gloss entry';
  end if;
end $$;

-- A word may already be covered by an active Indonesian phrase (a re-run
-- of this migration, or phrases created outside this import). A gloss
-- entry must then be fully covered by one shared phrase; a partially
-- covered entry is rejected instead of silently split.
create temp table _sfm_covered on commit drop as
select uw.n, uw.word_id, pw.phrase_id
from _sfm_unit_word as uw
join phrase_word as pw on pw.word_id = uw.word_id
join phrase as p on p.id = pw.phrase_id
where p.language_id = (select id from language where code = 'ind')
  and p.deleted_at is null;

do $$
begin
  if exists (
    select 1 from _sfm_covered group by n, word_id having count(*) > 1
  ) then
    raise exception 'Imported word covered by several active Indonesian phrases';
  end if;

  if exists (
    select 1
    from _sfm_unit_word as uw
    left join _sfm_covered as c on c.n = uw.n and c.word_id = uw.word_id
    group by uw.n
    having (count(c.phrase_id) > 0 and count(c.phrase_id) <> count(*))
       or count(distinct c.phrase_id) > 1
  ) then
    raise exception 'Gloss entry only partially covered by an existing phrase';
  end if;
end $$;

-- Create one phrase per uncovered gloss entry.
create temp table _sfm_new_phrase (n int primary key, id int not null) on commit drop;

with new_entry as (
  select g.n from _sfm_gloss as g
  where not exists (select 1 from _sfm_covered as c where c.n = g.n)
),
new_phrase as (
  select (select id from language where code = 'ind'), now(), null
  from new_entry
  returning id
)
select ne.n, np.id
from (select n, row_number() over (order by n) as rn from new_entry) as ne
join (select id, row_number() over (order by id) as rn from new_phrase) as np
  on np.rn = ne.rn;

select np.id, uw.word_id
from _sfm_new_phrase as np
join _sfm_unit_word as uw on uw.n = np.n;

create temp table _sfm_target on commit drop as
select
  g.n,
  coalesce(
    (select c.phrase_id from _sfm_covered as c where c.n = g.n limit 1),
    (select np.id from _sfm_new_phrase as np where np.n = g.n)
  ) as phrase_id,
  g.gloss as new_gloss
from _sfm_gloss as g;

do $$
begin
  if exists (select 1 from _sfm_target where phrase_id is null) then
    raise exception 'Gloss entry without a phrase';
  end if;

  if exists (
    select 1
    from _sfm_target as t
    join _sfm_unit_word as uw on uw.n = t.n
    where not exists (
      select 1 from phrase_word as pw
      where pw.phrase_id = t.phrase_id and pw.word_id = uw.word_id
    )
  ) then
    raise exception 'Phrase does not cover all words of its gloss entry';
  end if;

  if (select count(*) from _sfm_target) <> (select count(*) from _sfm_gloss) then
    raise exception 'Target phrase row count does not match gloss entry count';
  end if;
end $$;

-- Upsert the glosses. The (fixed) gloss suggestion triggers keep
-- lemma_form_suggestion in sync for single-word phrases (multi-word
-- phrases carry no suggestion count); unchanged rows are skipped so
-- re-running the migration fires no triggers at all.
select phrase_id, new_gloss, 'APPROVED', 'IMPORT', now(), null
from _sfm_target
on conflict (phrase_id) do update
set
  gloss = excluded.gloss,
  state = 'APPROVED',
  source = 'IMPORT',
  updated_at = excluded.updated_at,
  updated_by = null
where gloss.gloss is distinct from excluded.gloss
   or gloss.state <> 'APPROVED'
   or gloss.source <> 'IMPORT';

commit;
